begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(928976963375520)
,p_name=>'Class_wise_Fee_Amount'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'select cl.class_id, class_name, month_name,monthly_fee, bi_annual_fee, annual_fee ',
'from   months mo, fee_amount_m fm,fee_amount_d fd, class cl',
'where  fm.class_id = cl.class_id',
