'and    fd.fee_amount_m_id = fm.fee_amount_m_id  ',
'order by mo.month_id ;'))
,p_format=>'PDF'
,p_output_file_name=>'Class_wise_Fee_Amount'
,p_content_disposition=>'INLINE'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(929343877378594)
,p_shared_query_id=>wwv_flow_imp.id(928976963375520)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'select cl.class_id, class_name, month_name,monthly_fee, bi_annual_fee, annual_fee ',
'from   months mo, fee_amount_m fm,fee_amount_d fd, class cl',
'where  fm.class_id = cl.class_id',
