prompt --application/shared_components/reports/report_queries/classwise_daily_attendance
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(1000218395993650)
,p_name=>'Classwise_Daily_Attendance'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'select f_class_name(atm.class_id) class_name, ',
'       f_section_name(atm.section_id) section_name, attendance_date,',
'      roll_number, first_name||'' ''||last_name Student_name, status',
'from   attendance_m atm, student s, attendance_d ad',
'where  atm.attendance_m_id = ad.attendance_m_id',
'and    ad.student_id = s.student_id (+)',
'and  atm.class_id like nvl(:p_class_id,''%'')',
'and  atm.section_id like nvl(:p_section_id,''%'')',
'and   atm.attendance_date like  nvl(:p_ATTENDANCE_DATE, ''%'')',
'order  by  attendance_date desc  ;'))
,p_xml_structure=>'STANDARD'
,p_format=>'PDF'
,p_output_file_name=>'Classwise_Daily_Attendance'
,p_content_disposition=>'INLINE'
);
end;
/
prompt --application/shared_components/reports/report_queries/classwise_monthly_attendance
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(1001043264143088)
,p_name=>'Classwise_Monthly_Attendance'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select f_class_name(atm.class_id) , ',
'       f_section_name(atm.section_id) , to_char(attendance_date,''Month-RRRR'')  ,roll_number,',
'       first_name||'' ''||last_name , ad.student_id ,',
'                sum (CASE WHEN Status = ''Absent'' THEN 1',
'                  ELSE 0',
'             END) Total_Absent,',
'                sum(CASE WHEN Status = ''Present'' THEN 1',
'                  ELSE 0',
'             END) Total_present',
'from   attendance_m atm, student s, attendance_d ad',
'where    atm.attendance_m_id = ad.attendance_m_id',
'and    ad.student_id = s.student_id (+)',
'and  atm.class_id like nvl(:P_CLASS,''%'')',
'and  atm.section_id like nvl(:P_SECTION, ''%'')',
'--and to_char(attendance_date,''Month-RRRR'')  like :P_MONTHS ',
'group by f_class_name(atm.class_id), f_section_name(atm.section_id), to_char(attendance_date,''Month-RRRR''),',
'          roll_number,  first_name||'' ''||last_name,  ad.student_id',
'order  by  to_char(attendance_date,''Month-RRRR'')  desc  ;'))
,p_format=>'PDF'
,p_output_file_name=>'Classwise_Monthly_Attendance'
,p_content_disposition=>'INLINE'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(1554004713341977)
,p_shared_query_id=>wwv_flow_imp.id(1001043264143088)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select f_class_name(atm.class_id) class , ',
'       f_section_name(atm.section_id) section , to_char(attendance_date,''Month-RRRR'') months  ,roll_number,',
'       first_name||'' ''||last_name student_name , ad.student_id ,',
'                sum (CASE WHEN Status = ''Absent'' THEN 1',
'                  ELSE 0',
'             END) Total_Absent,',
'                sum(CASE WHEN Status = ''Present'' THEN 1',
'                  ELSE 0',
'             END) Total_present',
'from   attendance_m atm, student s, attendance_d ad',
'where    atm.attendance_m_id = ad.attendance_m_id',
'and    ad.student_id = s.student_id (+)',
'--and  atm.class_id like nvl(:P_CLASS,''%'')',
'--and  atm.section_id like nvl(:P_SECTION, ''%'')',
'--and to_char(attendance_date,''Month-RRRR'')  like :P_MONTHS ',
'group by f_class_name(atm.class_id), f_section_name(atm.section_id), to_char(attendance_date,''Month-RRRR''),',
'          roll_number,  first_name||'' ''||last_name,  ad.student_id',
'order  by  to_char(attendance_date,''Month-RRRR'')  desc  ;'))
);
end;
/
prompt --application/shared_components/reports/report_queries/studentwise_monthly_attendance
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(1003797059549016)
,p_name=>'Studentwise_Monthly_Attendance'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'SELECT ',
'    student_id, ',
'    student_name,',
'    months,',
'    SUM(CASE WHEN status = ''Absent'' THEN 1 ELSE 0 END) AS total_absent,',
'    sum(case when status = ''Present'' then 1 else 0 end ) as total_present, YEAR',
'FROM  student_ATTENDANCE_view',
'WHERE  student_id like nvl(:P_STUDENT, ''%'')',
'and    to_char(months,''Month _ RRRR'') like nvl(:p_MONTH, ''%'')',
'group by   student_id, ',
'    student_name,',
'    months, YEAR  ;'))
,p_format=>'PDF'
,p_output_file_name=>'Studentwise_Monthly_Attendance'
,p_content_disposition=>'INLINE'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(1446912123071650)
,p_shared_query_id=>wwv_flow_imp.id(1003797059549016)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    distinct',
'    student_name,',
'    months,',
'    SUM(CASE WHEN status = ''Absent'' THEN 1 ELSE 0 END) AS total_absent,',
'    sum(case when status = ''Present'' then 1 else 0 end ) as total_present, YEAR',
'FROM  student_ATTENDANCE_view',
'WHERE  student_id like nvl(:P_STUDENT, ''%'')',
'--and    to_char(months,''Month _ RRRR'') like nvl(:p_MONTH, ''%'')',
'group by  ',
'    student_name,',
'    months, YEAR  ;'))
);
end;
