prompt --application/shared_components/reports/report_queries/studentwise_fee_collection
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(1327026470221497)
,p_name=>'studentwise_fee_collection'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select student_id, sessions, class_id,COLLECTION_DATE,   MONTHLY_FEE,',
'        BI_ANNUAL_FEE,ANNUAL_FEE,TOTAL',
'from   fee_m fm, fee_d fd',
'where  fd.fee_m_id = fm.fee_m_id'))
,p_report_layout_id=>wwv_flow_imp.id(1370703479108075)
,p_format=>'PDF'
,p_output_file_name=>'studentwise_fee_collection'
,p_content_disposition=>'INLINE'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(1395654115944986)
,p_shared_query_id=>wwv_flow_imp.id(1327026470221497)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select F_ST_STD_NAME(student_id) student_name , sessions, f_class_name(class_id) class_name , to_char(COLLECTION_DATE,''dd-Mon-rrrr'')  COLLECTION_DATE,',
'        f_month_name(month_id) months, month_id, fd.MONTHLY_FEE,',
'        fd.BI_ANNUAL_FEE, fd.ANNUAL_FEE, TOTAL, total_amount, paid_amount, (case when nvl(total_amount, 0) =  nvl(paid_amount, 0) then ''Paid''',
'        else ',
'            ''Due''',
'         end ) status',
'from   fee_m fm, fee_d fd, fee_amount_d fa',
'where  fd.fee_m_id = fm.fee_m_id',
'and    fd.fee_amount_d_id = fa.fee_amount_d_id ',
'and    student_id like nvl(:p_student_id, ''%'')',
'and    sessions like nvl(:p_sessions, ''%'') ;',
'',
''))
);
end;
