prompt --application/shared_components/reports/report_queries/studentwise_result
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(1414262215950903)
,p_name=>'Studentwise_Result'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  year,class, st_name, roll_number,',
'  exam_category_name,subject_name,  obtained_marks,',
'  f_letter_grade( obtained_marks) letter_grade, case ',
'   when obtained_marks < ''33'' then ''Failed''',
'   when obtained_marks is null then ''Failed''',
'   else ''Passed''',
'   end Status, f_grade_point(obtained_marks) grade_point',
'from  result_view ',
'where student_id like nvl(:P104_STUDENT, ''%'')  ;',
''))
,p_format=>'PDF'
,p_output_file_name=>'Studentwise_Result'
,p_content_disposition=>'INLINE'
);
