,p_shared_query_id=>wwv_flow_imp.id(1414262215950903)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'SELECT DISTINCT ',
'  year,class, st_name,  roll_number, exam_category_name, subject_name,   obtained_marks,',
'  f_letter_grade(obtained_marks) letter_grade, ',
'  CASE ',
'    WHEN obtained_marks < ''33'' THEN ''Failed''',
'    WHEN obtained_marks IS NULL THEN ''Failed''',
'    ELSE ''Passed''',
'  END Status, ',
'  f_grade_point(obtained_marks) grade_point',
'FROM  ',
'  result_view ',
''))
);
end;
