,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH',
'---------Total_student Query --------',
'Total_student',
'AS',
'(',
'select count(student_id) Total_student',
'from student',
'),',
'---------Total_employee Query --------',
'Total_Teacher',
'AS',
'(',
'select count(employee_id) Total_Teacher',
'from employee',
'),',
'--------------------------------',
'---------Total_User Query --------',
'Total_User',
'AS',
'(',
'select count(username) Total_User',
'from user_info',
')',
'--------------------------------',
'-------Total_student Value Set -------',
'SELECT',
'''icon'' AS CARD_TYPE,',
'DECODE(ROWNUM, 1, ''fa-pie-chart'', 2, ''fa-pie-chart'', ''fa-pie-chart'') AS CARD_ICON,',
'NULL AS CARD_ICON_COLOR,',
'NULL AS CARD_HEADER_STYLE,',
'''Total student'' AS CARD_TITLE,',
'Total_student AS CARD_VALUE,',
''' Total Student of School'' AS CARD_FOOTER,',
'''https://apex.oracle.com/pls/apex/r/nursoft/ddd-56%40isdb-bisew/total-employee-reportplugin?session='' || :APP_SESSION AS CARD_LINK,',
'NULL AS CARD_CHART_DATA,',
'NULL AS CARD_CHART_CONFIG',
'FROM Total_student',
'----------------------------------------',
'UNION ALL',
'-------Total_employee Value Set -------',
'SELECT',
'''icon'' AS CARD_TYPE,',
'DECODE(ROWNUM, 1, ''fa-bar-chart'', 2, ''fa-bar-chart'', ''fa-bar-chart'') AS CARD_ICON,',
'NULL AS CARD_ICON_COLOR,',
'NULL AS CARD_HEADER_STYLE,',
'''Total Teacher'' AS CARD_TITLE,',
'Total_Teacher AS CARD_VALUE,',
'''Total Teacher of School'' AS CARD_FOOTER,',
'''https://apex.oracle.com/pls/apex/r/nursoft/apex-20-ibcs/call-emp-reportplug-ins-dashboard?session='' ',
'|| :APP_SESSION AS CARD_LINK,',
'NULL AS CARD_CHART_DATA,',
'NULL AS CARD_CHART_CONFIG',
'FROM Total_Teacher',
'----------------------------------------',
'',
'UNION ALL',
'-------Total_User Value Set -------',
'SELECT',
'''icon'' AS CARD_TYPE,',
'DECODE(ROWNUM, 1, ''fa-bar-chart'', 2, ''fa-bar-chart'', ''fa-bar-chart'') AS CARD_ICON,',
'NULL AS CARD_ICON_COLOR,',
'NULL AS CARD_HEADER_STYLE,',
'''Total User'' AS CARD_TITLE,',
'Total_User AS CARD_VALUE,',
''' Total User '' AS CARD_FOOTER,',
