,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "CLASS_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P16_CLASS_ID'', p_values => "CLASS_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P16_CLASS_ID,''0'') = "CLASS_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr("CLASS_NAME", 1, 50)||( case when length("CLASS_NAME") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("CLASS_DESCRIPTION", 1, 50)||( case when length("CLASS_DESCRIPTION") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "CLASS" x',
'where (:P16_SEARCH is null',
'        or upper(x."CLASS_NAME") like ''%''||upper(:P16_SEARCH)||''%''',
'        or upper(x."CLASS_DESCRIPTION") like ''%''||upper(:P16_SEARCH)||''%''',
'    )',
'order by "CLASS_NAME"'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P16_SEARCH'
