,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "EXPENSE_M_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P17_EXPENSE_M_ID'', p_values => "EXPENSE_M_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P17_EXPENSE_M_ID,''0'') = "EXPENSE_M_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr(TO_CHAR("EXPENSE_DATE",''DD, Month rrrr''), 1, 50)||( case when length(TO_CHAR("EXPENSE_DATE", ''DD, Month rrrr'')) > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("DEPARTMENT_NAME", 1, 50)||( case when length("DEPARTMENT_NAME") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "EXPENSE_M" x, "DEPARTMENT" Y',
'where (:P17_SEARCH is null',
'        or upper(x."EXPENSE_DATE") like ''%''||upper(:P17_SEARCH)||''%''',
'        or upper(Y."DEPARTMENT_NAME") like ''%''||upper(:P17_SEARCH)||''%''',
'    )',
'    AND X.DEPARTMENT_ID = Y.DEPARTMENT_ID (+)',
'order by "EXPENSE_M_ID" DESC ;'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P17_SEARCH'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(73822941691228320652)
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'<div class="u-tC">No data found.</div>'
