,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'htp.p(''<style>',
'table',
'{',
' border: 2px solid green;',
' border-collapse: collapse;',
'}',
'th ',
'{',
' border: 1px solid blue;',
' background-color:pink;',
' font-size: 14px;',
' padding: 3px 6px;',
'}',
'td ',
'{',
' border: 1px solid black;',
' text-align: center;',
' padding: 3px 5px;',
'}',
'</style>'');',
'',
'----------------- Column Heading -----------------',
'htp.p(''<center> <table style="width:100%">',
'<tr>',
' <th style="width: 110px">Admission ID</th>',
' <th>Student Name</th> ',
'---<th>Fathers Name</th> ',
' <th>Gender</th> ',
' <th style="width: 160px">Birth Reg Number</th>',
' <th style="width: 150px">Class Name</th>',
' <th style="width: 150px">Admission Date</th>',
' </tr>'');',
'------------ Type your Query ------------------------------------------',
'FOR nur in (select admission_id, first_name||'' ''||last_name student_name,fathers_name,  gender,birth_reg_number,',
'       class_name,to_char(admission_date, ''DD-Mon-RRRR'') admission_date',
'from  admission ad, class cl',
'where  ad.class_id = cl.class_id (+)',
'and    ad.class_id  like nvl(:P42_CLASS, ''%'')',
'and    to_char(admission_date, ''rrrr'') like nvl(:P42_SESSIONS, ''%'')',
'order by admission_id )',
'----------------------------------------------------------------------',
'----------------- Column Data -----------------',
' LOOP',
' htp.p(''<tr>',
' <td style="text-align: center">''||htf.escape_sc(nur.Admission_id)||''</td>',
' <td style="text-align: Left">''||htf.escape_sc(nur.student_name)||''</td>',
'  <td style="text-align: Left">''||htf.escape_sc(nur.fathers_name)||''</td>',
'  <td style="text-align: CENTER">''||htf.escape_sc(nur.gender)||''</td>',
' <td style="text-align: right">''||htf.escape_sc(nur.birth_reg_number)||''</td>',
' <td style="text-align: center">''||htf.escape_sc(nur.class_name)||''</td>',
' <td style="text-align: center">''||htf.escape_sc(nur.admission_date)||''</td>',
' <tr>'');',
'END LOOP;',
'htp.p('' </table></center>'') ;',
'',
'end ;'))
,p_plug_source_type=>'NATIVE_PLSQL'
);
