,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'',
'declare',
' V_COMPANY_NAME VARCHAR2(100) := ''AL-Hera Academy & School'' ;',
' cursor nur is ',
'------------------------------------------------------',
' select SALES_INVOICE, SALES_DATE, CUSTOMER_ID, nvl(DISCOUNT,0)DISCOUNT,',
' nvl(GROSS_AMOUNT,0)GROSS_AMOUNT,nvl(VAT,0)VAT,nvl(VAT_AMOUNT,0)VAT_AMOUNT, ',
