'nvl(DUE_AMOUNT,0)DUE_AMOUNT',
' FROM SALES_M',
' WHERE SALES_INVOICE = :P48_SALES_INVOICE ;',
'------------------------------------------------------',
' record_nur nur%rowtype;',
' V_CUSTOMER_NAME VARCHAR2(100);',
' V_CUS_ADDRESS VARCHAR2(100);',
' V_PHONE_NUMBER1 VARCHAR2(50);',
' V_taka_in_word varchar2(3000);',
'begin',
'--------------------------------',
'',
'',
