' ',
'<div id="div_print1" style="margin-top:5px;"> ''); ',
'---------------------',
'OPEN nur;',
'FETCH nur INTO record_nur;',
'CLOSE nur;',
'select CUSTOMER_NAME, CUSTOMER_ADDRESS, CELL_NUMBER ',
'INTO V_CUSTOMER_NAME, V_CUS_ADDRESS, V_PHONE_NUMBER1 ',
'FROM CUSTOMER ',
'WHERE CUSTOMER_ID = record_nur.CUSTOMER_ID ;',
'-------------------------------',
'htp.p(''',
' <html>',
' <header>',
' <title>Invoice</title>',
' <meta charset="utf-8">',
' <meta name="viewport" content="width=device-width, initial-scale=1">',
