 p_id=>48
,p_name=>'Sales_MD'
,p_alias=>'SALES-MD'
,p_step_title=>'Sales_MD'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function($) ',
'{',
' function update(model) ',
' {',
' var salKey = model.getFieldKey("TOTAL_UNIT_PRICE"),',
' total = 0;',
' console.log(">> starting sum TOTAL_UNIT_PRICE column")',
' model.forEach(function(record, index, id) ',
' {',
' var sal = parseFloat(record[salKey]), ',
' meta = model.getRecordMetadata(id);',
' if (!isNaN(sal) && !meta.deleted && !meta.agg) ',
' {',
' total += sal;',
' }',
' });',
' console.log(">> setting sum SAL column to " + total)',
' $s("P48_GROSS_AMOUNT", total);',
' }',
' $(function() ',
' {',
' $("#nur").on("interactivegridviewmodelcreate", function(event, ui) ',
' {',
' var sid,',
' model = ui.model;',
' if ( ui.viewId === "grid" ) ',
' {',
' sid = model.subscribe( ',
' {',
' onChange: function(type, change) ',
'',
'{',
' console.log(">> model changed ", type, change);',
' if ( type === "set" ) ',
' {',
' ',
' if (change.field === "TOTAL_UNIT_PRICE" ) ',
' {',
' update( model );',
' }',
' } else if (type !== "move" && type !== "metaChange") ',
' {',
' ',
' update( model );',
' }',
' },',
' progressView: $("#P48_GROSS_AMOUNT") ',
' } );',
' update( model );',
' model.fetchAll(function() {});',
' }',
' });',
' });',
' })(apex.jQuery);',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$(',
'''body'').on(''keydown'', ''input, select, textarea'', function(e) {',
'    var self = $(this)',
'      , form = self.parents(''form:eq(0)'')',
'      , focusable',
'      , next',
'      ;',
'    if (e.keyCode == 13) {',
'        focusable = form.find(''input,select,textarea,tabindex'').filter('':visible'');',
'        next = focusable.eq(focusable.index(this)+1);',
'        if (next.length) {',
'            next.focus();',
'        } else {',
'            form.submit();',
'        }',
'        return false;',
'    }',
'});',
'',
''))
