,p_process_name=>'Process_d'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
' case :APEX$ROW_STATUS ',
' when ''C'' then',
' insert into class_info( subject_id) ',
' values( :subject_id) ;',
' when ''U'' then',
' update class_info  ',
' set',
'      subject_id = :subject_id  ',
'      where rowid = :rowid ; ',
'when ''D''  then  ',
' delete from class_info  ',
'  where rowid = :rowid ; ',
'  end case ;',
'',
'exception ',
' when others then ',
'  raise_application_error(-20010, sqlerrm) ; ',
'end ;'))
,p_process_clob_language=>'PLSQL'
