,p_plug_name=>'Monthly Class wise  Attendance Count Report'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(73822896867649320629)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select f_class_name(atm.class_id) , ',
'       f_section_name(atm.section_id) , to_char(attendance_date,''Month-yyyy'') months, roll_number,',
'       first_name||'' ''||last_name student_name ,',
'                sum (CASE WHEN Status = ''Absent'' THEN 1',
'                  ELSE 0',
'             END) Total_Absent,',
'                sum(CASE WHEN Status = ''Present'' THEN 1',
'                  ELSE 0',
'             END) Total_present',
'from   attendance_m atm, student s, attendance_d ad',
'where    atm.attendance_m_id = ad.attendance_m_id',
'and    ad.student_id = s.student_id (+)',
'and  atm.class_id like nvl(:P93_CLASS,''%'')',
'and  atm.section_id like nvl(:P93_SECTION, ''%'')',
'and to_char(attendance_date,''Month-yyyy'')  like :P93_MONTHS ',
'group by f_class_name(atm.class_id), f_section_name(atm.section_id), to_char(attendance_date,''Month-yyyy''),',
'          roll_number,  first_name||'' ''||last_name',
'order  by  to_char(attendance_date,''Month-yyyy'')  desc  ;',
'',
'',
'',
''))
