'    apex_page.get_url(p_items => ''P94_MENU_ACCESS_M_ID'', p_values => "MENU_ACCESS_M_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P94_MENU_ACCESS_M_ID,''0'') = "MENU_ACCESS_M_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr("USERNAME", 1, 50)||( case when length("USERNAME") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("ACTION_USER", 1, 50)||( case when length("ACTION_USER") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "MENU_ACCESS_M" x',
'where (:P94_SEARCH is null',
'        or upper(x."USERNAME") like ''%''||upper(:P94_SEARCH)||''%''',
'        or upper(x."ACTION_USER") like ''%''||upper(:P94_SEARCH)||''%''',
'    )',
'order by "USERNAME"'))
