'<td width="100px" align=center>''||''''||htf.escape_sc(r.months)||''</td>',
'<td width="100px" align=right>''||'' ''||htf.escape_sc(to_char((r.Monthly_fee), ''99,99,99,999.00''))||''</td>',
'<td width="100px" align=right>''||'' ''||htf.escape_sc(to_char((r.BI_ANNUAL_FEE), ''99,99,99,999.00''))||''</td>',
'<td width="100px" align=right>''||'' ''||htf.escape_sc(to_char((r.ANNUAL_FEE), ''99,99,99,999.00''))||''</td>',
'<td width="100px" align=right>''||'' ''||htf.escape_sc(to_char((r.TOTAL), ''99,99,99,999.00''))||''</td>',
'</tr>',
'</tbody>',
''');',
'end loop;',
'htp.p(''',
'</table>',
'</body>',
''');',
'htp.p(''',
'',
'<td class="td1">',
'<table class="patient2" align="right">',
'<tr>',
'<th class="p1">Total Amount :</th>',
'<td class="p1"> &nbsp; ''||to_char(record_nur.TOTAL_AMOUNT,''99,99,99,999.99'')||''</td>',
