wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(99337039730293389793)
,p_name=>'Master Records'
,p_template=>wwv_flow_imp.id(73822841315586320599)
,p_display_sequence=>20
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "ROUTINE_M_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P1051_ROUTINE_M_ID'', p_values => "ROUTINE_M_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P1051_ROUTINE_M_ID,''0'') = "ROUTINE_M_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'--    (substr(f_emp_name("EMPLOYEE_ID"), 1, 50)||( case when length(f_emp_name("EMPLOYEE_ID")) > 50 then ''...'' else '''' end )) LIST_TITLE,',
'x.employee_id||'' - ''||first_name||'' ''||last_name||'' - (''||',
'       (select count(class_d_id)',
'       from   routine_d rd, routine_m rm',
'       where  employee_id = e.employee_id',
'       and    rd.ROUTINE_M_ID = rm.ROUTINE_M_ID)||'')'' LIST_TITLE,',
'--    (substr("DAY_OF_WEEK", 1, 50)||( case when length("DAY_OF_WEEK") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'DAY_OF_WEEK||'' - (''||',
'       (select count(class_d_id)',
'       from   routine_d rd, routine_m rm',
'       where  employee_id = e.employee_id',
'       and    rd.ROUTINE_M_ID = rm.ROUTINE_M_ID',
'       and    day_of_week = x.day_of_week)||'')'' LIST_TEXT,',
'    null LIST_BADGE',
'from "ROUTINE_M" x, employee e',
'where (:P1051_SEARCH is null',
'        or upper(f_emp_name(x."EMPLOYEE_ID")) like ''%''||upper(:P1051_SEARCH)||''%''',
'        or upper(x."DAY_OF_WEEK") like ''%''||upper(:P1051_SEARCH)||''%''',
'    )',
'    and x.employee_id = e.employee_id',
'order by x.EMPLOYEE_ID asc, "DAY_OF_WEEK" asc, routine_m_id desc'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P1051_SEARCH'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(73822941691228320652)
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'<div class="u-tC">No data found.</div>'
,p_query_row_count_max=>500
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
