'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P1060_EXAM_M_ID,''0'') = "EXAM_M_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'--    (substr("ACTION_USER", 1, 50)||( case when length("ACTION_USER") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'     ''Exam ID - ''||exam_M_ID||'' Session - ''||sessions LIST_TITLE,',
'--    (substr("ACTION_USER", 1, 50)||( case when length("ACTION_USER") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'      f_class_name(class_id)||'' - ''||f_section_name(section_id)||'' - ''||f_exam_category_name(exam_category_id)      LIST_TEXT,',
'    null LIST_BADGE',
'from "EXAM_M" x',
'where (:P1060_SEARCH is null',
'        or upper(x."ACTION_USER") like ''%''||upper(:P1060_SEARCH)||''%''',
'        or upper(x."ACTION_USER") like ''%''||upper(:P1060_SEARCH)||''%''',
'    )',
'order by "EXAM_M_ID" desc'))
