prompt --application/pages/page_01070
begin
wwv_flow_imp_page.create_page(
 p_id=>1070
,p_name=>'Fee Collection'
,p_alias=>'FEE-COLLECTION'
,p_step_title=>'Fee Collection'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function($)',
'{',
' function update(model)',
' {',
' var salKey = model.getFieldKey("TOTAL"),',
' total = 0;',
' console.log(">> starting sum TOTAL column")',
' model.forEach(function(record, index, id)',
' {',
' var sal = parseFloat(record[salKey]),',
' meta = model.getRecordMetadata(id);',
' if (!isNaN(sal) && !meta.deleted && !meta.agg)',
' {',
' total += sal;',
' }',
' });',
' console.log(">> setting sum SAL column to " + total)',
' $s("P1070_TOTAL_AMOUNT", total);',
' }',
' $(function()',
' {',
' $("#feesgrid").on("interactivegridviewmodelcreate", function(event, ui)',
' {',
' var sid,',
' model = ui.model;',
' if ( ui.viewId === "grid" )',
' {',
' sid = model.subscribe(',
' {',
' onChange: function(type, change)',
'{',
' console.log(">> model changed ", type, change);',
' if ( type === "set" )',
' {',
'',
' if (change.field === "TOTAL" )',
' {',
' update( model );',
' }',
' } else if (type !== "move" && type !== "metaChange")',
' {',
'',
' update( model );',
' }',
' },',
' progressView: $("#P1070_TOTAL_AMOUNT")',
' } );',
' update( model );',
' model.fetchAll(function() {});',
' }',
' });',
' });',
' })(apex.jQuery);'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.apex_disabled {',
'    opacity: 100%!important;',
'}'))
